import{_ as t}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as r}from"./chunks/HR工作台.BKqxKIe0.js";import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-01.D_iyhWsf.png",i="/newx-doc/assets/%E7%AC%AC%E4%B8%80%E6%AD%A5-02.Bsy5p0U5.png",n="/newx-doc/assets/%E7%AC%AC%E4%BA%8C%E6%AD%A5-01.CDxiaiRr.png",A=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"hrm/build.md","filePath":"hrm/build.md","lastUpdated":null}'),l={name:"hrm/build.md"};function m(p,e,h,u,_,g){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><p>进度说明：</p><ul><li>管理后台，请使用 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-ui-admin-vue3</a> 仓库的 <code>master</code> 分支</li><li>后端项目，请使用 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://gitee.com/zhijiantianya/ruoyi-vue-pro</a> 仓库的 <code>master</code>（JDK8）、<code>master-jdk17</code>（JDK17/21）或 <code>master-jdk25</code>（JDK25）分支</li></ul><p>HRM 系统，后端由 <code>yudao-module-hrm</code> 模块实现，前端由 <code>yudao-ui-admin-vue3</code> 的 <code>hrm</code> 目录实现。</p><p>考虑到编译速度，默认 <code>yudao-module-hrm</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-hrm</code> 模块</li><li>第二步，导入 HRM 系统的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><p>补充说明：</p><p>由于 HRM 请假使用到 BPM 的审批功能，所以你需要先看 <a href="./../bpm">《工作流》</a> 文档，将工作流开启！</p><h2 id="_1-第一步-开启模块" tabindex="-1">1. 第一步，开启模块 <a class="header-anchor" href="#_1-第一步-开启模块" aria-label="Permalink to &quot;1. 第一步，开启模块&quot;">​</a></h2><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-hrm</code> 模块的注释。如下图所示：</p><p><img src="'+s+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-hrm</code> 模块。如下图所示：</p><p><img src="'+i+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+t+'" alt="刷新 Maven 依赖"></p><h2 id="_2-第二步-导入-sql" tabindex="-1">2. 第二步，导入 SQL <a class="header-anchor" href="#_2-第二步-导入-sql" aria-label="Permalink to &quot;2. 第二步，导入 SQL&quot;">​</a></h2><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/hrm.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。如下图所示：</p><p>友情提示：↑↑↑ hrm.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><p><img src="'+n+'" alt="导入数据库"></p><p>以 <code>hrm_</code> 作为前缀的表，就是 HRM 模块的表，一共 <strong>50</strong> 张，按业务模块分为：</p><table tabindex="0"><thead><tr><th>子前缀</th><th>模块</th><th>表数量</th></tr></thead><tbody><tr><td><code>hrm_config</code></td><td>共享配置</td><td>1</td></tr><tr><td><code>hrm_employee*</code></td><td>员工管理</td><td>12</td></tr><tr><td><code>hrm_recruit_*</code></td><td>招聘管理</td><td>5</td></tr><tr><td><code>hrm_attendance_*</code></td><td>考勤管理</td><td>4</td></tr><tr><td><code>hrm_insurance_*</code></td><td>社保管理</td><td>5</td></tr><tr><td><code>hrm_salary_*</code></td><td>薪资管理</td><td>13</td></tr><tr><td><code>hrm_performance_*</code></td><td>绩效管理</td><td>10</td></tr></tbody></table><h2 id="_3-第三步-重启项目" tabindex="-1">3. 第三步，重启项目 <a class="header-anchor" href="#_3-第三步-重启项目" aria-label="Permalink to &quot;3. 第三步，重启项目&quot;">​</a></h2><p>重启后端项目，然后访问前端的 HRM 菜单，确认功能是否生效。如下图所示：</p><p><img src="'+r+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了 HRM 的功能 🙂</p><h2 id="_4-全局说明" tabindex="-1">4. 全局说明 <a class="header-anchor" href="#_4-全局说明" aria-label="Permalink to &quot;4. 全局说明&quot;">​</a></h2><p>① HRM 的<strong>基础数据来自 System 模块</strong>：部门复用 <code>system_dept</code>，后台账号复用 <code>system_users</code>。建议先完成组织与员工档案，再配置考勤、社保、薪资和绩效，避免月度计算缺少员工基础资料。</p><p>② HRM 区分<strong>管理端</strong>与<strong>员工端</strong>两套菜单，但共用同一个后台账号体系。SQL 导入后，需要为 HR、主管和员工角色分别分配菜单；员工端还要先在员工档案中把 <code>hrm_employee.user_id</code> 绑定到 <code>system_users.id</code>。未绑定员工档案的账号只会看到开通引导，详见 <a href="./organization">《【组织】工作台、组织架构》</a>。</p><p>③ <strong>请假审批复用 BPM</strong>：员工请假的流程定义 Key 固定为 <code>hrm_attendance_leave</code>，审批完成后由 HrmAttendanceLeaveStatusListener 回写请假状态，详见 <a href="./attendance">《【考勤】考勤管理》</a>。</p><p>④ <strong>预约生效依赖定时任务</strong>：在 [基础设施 -&gt; 定时任务] 中配置 HrmEmployeeChangeJob、HrmSalaryChangeJob 和 HrmPerformanceAppealTimeoutJob，分别处理到期的人事异动与离职、到期的调薪，以及超时的绩效申诉节点。未配置时，预约生效的记录会一直停留在待生效状态。（如果是微服务版本，需要去 XXL-Job 里去配置）</p>',31)])])}const x=o(l,[["render",m]]);export{A as __pageData,x as default};
